def select(t, *names):
    return [image(t, name) for name in names]


def replace(t, blocks):
    card = next(b for b in t['blocks'] if b['type'] == 'idcard')
    handoff = next(b for b in t['blocks'] if b['type'] == 'handoff')
    handoff['open'] = ('پیش از انتشار، متن این مبحث را با صفحه‌های منبع مقابله کنید.'
                       if t['topic_id'].startswith('hn01-') else
                       'رونویسی این مبحث هنوز به مقابلهٔ مستقل واژه‌به‌واژه و بازبینی علمی نیاز دارد.')
    t['blocks'] = [card, *blocks, handoff]


def src_list(items, page, ordered=False):
    return {'type': 'ol' if ordered else 'ul', 'items': items, 'src': f'متن جزوهٔ درس، ص {page} — رونویسی در حال مقابله'}


